const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // Define Hotan/Taklamakan area
  const hotan = ee.Geometry.Point([79.9, 37.1]);
  const aoi = hotan.buffer(50000); // 50km buffer

  // Date ranges
  const startFeb = '2020-02-15';
  const endFeb = '2020-03-05';
  const startApr = '2020-04-15';
  const endApr = '2020-05-10';

  // Sentinel-2 with cloud masking
  const s2 = ee.ImageCollection('COPERNICUS/S2_SR')
    .filterBounds(aoi)
    .filter(ee.Filter.lt('CLOUDY_PIXEL_PERCENTAGE', 30));

  // February collection
  const febCollection = s2.filterDate(startFeb, endFeb);
  const febCount = febCollection.size().getInfo();

  // April collection
  const aprCollection = s2.filterDate(startApr, endApr);
  const aprCount = aprCollection.size().getInfo();

  console.log(`Feb Images: ${febCount}, Apr Images: ${aprCount}`);

  if (febCount === 0 || aprCount === 0) {
    console.log('C1');
    return;
  }

  // Function to calculate NDVI and valid pixels
  function calculateNDVI(collection) {
    return collection.map(img => {
      const ndvi = img.normalizedDifference(['B8', 'B4']).rename('NDVI');
      const cloudMask = img.select('QA60')
        .bitwiseAnd(1 << 10).eq(0)
        .and(img.select('QA60').bitwiseAnd(1 << 11).eq(0));
      return ndvi.updateMask(cloudMask);
    }).mean();
  }

  const febNDVI = calculateNDVI(febCollection);
  const aprNDVI = calculateNDVI(aprCollection);

  // Check valid pixels for February
  const febValidPixels = febNDVI.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: aoi,
    scale: 1000,
    maxPixels: 1e9
  }).get('NDVI').getInfo();

  // Check valid pixels for April
  const aprValidPixels = aprNDVI.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: aoi,
    scale: 1000,
    maxPixels: 1e9
  }).get('NDVI').getInfo();

  console.log(`Feb Valid Pixels: ${febValidPixels}, Apr Valid Pixels: ${aprValidPixels}`);

  if (febValidPixels === 0 || aprValidPixels === 0) {
    console.log('C2');
    return;
  }

  // Calculate mean NDVI
  const febMean = febNDVI.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: aoi,
    scale: 1000,
    maxPixels: 1e9
  }).get('NDVI').getInfo();

  const aprMean = aprNDVI.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: aoi,
    scale: 1000,
    maxPixels: 1e9
  }).get('NDVI').getInfo();

  console.log(`Feb Mean NDVI: ${febMean !== null ? febMean.toFixed(4) : 'null'}, Apr Mean NDVI: ${aprMean !== null ? aprMean.toFixed(4) : 'null'}`);

  if (febMean === null || aprMean === null || isNaN(febMean) || isNaN(aprMean)) {
    console.log('C3');
    return;
  }

  if (febMean < -1 || febMean > 1 || aprMean < -1 || aprMean > 1) {
    console.log('C3');
    return;
  }

  // Compare vegetation cover
  const ndviIncrease = aprMean > febMean;
  console.log(`NDVI Increase (Apr > Feb): ${ndviIncrease}`);

  if (ndviIncrease) {
    console.log('A');
  } else {
    console.log('B');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
